cssCode:
.offer-badge {
  padding: 10px 20px;
  background: #ff0055; color: #fff;
  font-family: sans-serif; font-weight: 900; font-size: 18px;
  border-radius: 8px; letter-spacing: 1px;
  box-shadow: 0 0 0 0 rgba(255, 0, 85, 0.7);
  animation: pulseBadge 1.5s infinite cubic-bezier(0.66, 0, 0, 1);
}
@keyframes pulseBadge {
  to { box-shadow: 0 0 0 20px rgba(255, 0, 85, 0); transform: scale(1.05); }
}

